var $sc = screen("dash",0)
var $ahs = screen("dashAH",0)
var $blankColor = color(6,6,6)

include "widget.xc"
include "driving.main.xc"

init
	$sc.blank($blankColor)

tick
	; Anchor
	if input_number("dashtop",11)
		output_number("anchor",0,1)
	else
		output_number("anchor",0,0)	

	; Master
	if input_number("dashtop",1)
		; Drill
		if input_number("dashtop",12)
			output_number("drill",0,1)
		else
			output_number("drill",0,0)

		; Main Dashboard Stuff
		$sc.draw(0,0,$blankColor,200,10)
		$sc.draw(0,10,color(30,30,30),200,1)
		$sc.write(1,1,color(0,80,100),text("Alt: {0}m",input_number("alt",0)-6203000))
		$sc.write(90,1,color(0,80,100),text("Speed: {0}km/h",input_number("speed",0)*3.6))	
		@ah(0,0,0,$ahs)
		@batteryGauge(181,1,$blankColor,$sc,(input_number("bat1",2)+input_number("bat2",2))*100/2)
		@drillComposition(106,12,$blankColor,$sc,(input_text("drill",0)))
		@oreScanner(52,55,40,$blankColor,$sc,"pivotscanner","scanner")


	else
		output_number("pivotscanner",0,0)
		$ahs.blank(0)
		$sc.blank()
